      QUEST_RemoveQuestItemFromPlayer(pGame, pUnit, 0x20726271);
      QUEST_RemoveQuestItemFromPlayer(pGame, pUnit, 0x20316671);
      QUEST_RemoveQuestItemFromPlayer(pGame, pUnit, 0x20326671);
